const item = $input.first();
const agentData = $('Estrai JSON dall\'agente2').first().json;
const sessionId = agentData.session_id;
const objectName = agentData.object_name;
const seed = agentData.seed;

// Il nodo comfyui mason276752 restituisce le immagini come binary
// La chiave binary può essere 'data', 'image', o il filename
const binaryKeys = Object.keys(item.binary ?? {});
console.log('Binary keys disponibili da FLUX:', JSON.stringify(binaryKeys));
console.log('JSON da FLUX:', JSON.stringify(item.json).substring(0, 400));

if (binaryKeys.length === 0) {
  throw new Error(`Nessun binary trovato nell output FLUX. JSON: ${JSON.stringify(item.json).substring(0, 300)}`);
}

const binaryKey = binaryKeys[0];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64Image = buffer.toString('base64');

const dataUri = base64Image;

console.log(`Immagine convertita: ${Math.round(buffer.length / 1024)}KB, key: ${binaryKey}`);

return [{ json: {
  image_base64: dataUri,
  session_id: sessionId,
  object_name: objectName,
  seed: seed
} }];

// Polling del GLB legato a QUESTA esecuzione (tramite prompt_id di ComfyUI)
const history   = $input.first().json;
const agentData = $('Dati richiesta 3D').first().json;
const promptId  = $('Comfy3D - Pixal').first().json.prompt_id;
if (!promptId) throw new Error('prompt_id mancante nella risposta di Comfy3D - Pixal');

// Annullata dall'utente? (riga scritta dal workflow quest-cancel)
const cancelRow = $('Annullata? (polling)').first().json;
if (cancelRow?.session_id && cancelRow.session_id === agentData.session_id) {
  throw new Error(`Richiesta annullata dall'utente (sessione ${agentData.session_id})`);
}

const attempts = $runIndex + 1;
const MAX_ATTEMPTS = 90;          // con Wait da 10 s = 15 minuti

const entry = history[promptId];
if (entry?.status?.status_str === 'error') {
  throw new Error(`ComfyUI: esecuzione fallita o interrotta per ${promptId} — ${JSON.stringify(entry.status.messages ?? []).substring(0, 300)}`);
}

// Cerca il .glb (preferendo i file salvati, type "output")
const glbs = [];
for (const out of Object.values(entry?.outputs ?? {})) {
  for (const val of Object.values(out ?? {})) {
    if (!Array.isArray(val)) continue;
    for (const f of val) {
      if (typeof f?.filename === 'string' && f.filename.toLowerCase().endsWith('.glb')) glbs.push(f);
    }
  }
}
const glb = glbs.filter(f => (f.type ?? 'output') === 'output').at(-1) ?? glbs.at(-1) ?? null;

if (!glb) {
  if (entry?.status?.completed) {
    throw new Error(`Prompt ${promptId} completato ma nessun .glb trovato. Outputs: ${JSON.stringify(entry.outputs).substring(0, 400)}`);
  }
  if (attempts >= MAX_ATTEMPTS) throw new Error(`Timeout: nessun GLB per ${promptId} dopo ${attempts} tentativi`);
  return [{ json: { _ready: false, _attempts: attempts, prompt_id: promptId } }];
}

const host = '10.54.15.50';
const port = 8188;
const glbUrl = `http://${host}:${port}/view?filename=${encodeURIComponent(glb.filename)}`
  + `&type=${glb.type || 'output'}&subfolder=${encodeURIComponent(glb.subfolder ?? '')}`;

return [{ json: {
  _ready: true,
  _attempts: attempts,
  status: 'ready',
  glb_url: glbUrl,
  prompt_id: promptId,
  object_name: agentData.object_name,
  session_id: agentData.session_id,
  flux_prompt: agentData.flux_prompt,
  message: 'Oggetto generato con successo!'
}}];

console.log('✅ Pipeline completata!');
console.log('GLB URL:', $json.glb_url);
console.log('Oggetto:', $json.object_name);
console.log('Tentativi:', $json._attempts);
return [$input.first()];

// Un solo webhook, due fasi: action = "image" (anteprima, ripeti, correzioni) | "model" (3D dall'immagine approvata)
const data = $input.first().json;
const b = data.body ?? data;

const action = String(b.action ?? 'image').toLowerCase() === 'model' ? 'model' : 'image';
const msg = (b.prompt ?? data.chatInput ?? data.input ?? data.message ?? 'una sedia medievale').toString();
const sessionId = b.session_id ?? ('test_' + Date.now().toString());

return [{ json: {
  action,
  prompt: msg.trim(),
  session_id: sessionId,
  image_path: b.image_path ?? '',
  object_name: b.object_name ?? '',
  flux_prompt: b.flux_prompt ?? '',
  seed: b.seed ?? ''
} }];

